-- Datos de prueba para desarrollo local (no es una migración).
-- Supabase los carga solo al reconstruir la base local con:  npx supabase db reset
-- Incluye los usuarios de prueba (mismas contraseñas que se usaron al crearlos),
-- las empresas, sus miembros, objetos y eventos. Las fotos de los objetos están en
-- ./seed/event-files y se suben al bucket «event-files» en el mismo paso (ver config.toml).
-- Generado con pg_dump --data-only --column-inserts --on-conflict-do-nothing.

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
